alloc.content:
inline int LevelMesh::AllocTile(const LightmapTile& tile)
{
	Lightmap.UsedTiles++;
	if (Lightmap.FreeTiles.Size() != 0)
	{
		int index = Lightmap.FreeTiles.Last();
		Lightmap.FreeTiles.Pop();
		Lightmap.Tiles[index] = tile;
		MarkMutation(LevelMeshMutationDomain::LightmapProbe);
		return index;
	}
	int index = Lightmap.Tiles.Size();
	Lightmap.Tiles.Push(tile);
	MarkMutation(LevelMeshMutationDomain::LightmapProbe);
	return index;
}

free.content:
inline void LevelMesh::FreeTile(int index)
{
	if (index < 0 || index >= (int)Lightmap.Tiles.Size() || Lightmap.UsedTiles <= 0)
		I_FatalError("Invalid LevelMesh lightmap tile free: %d", index);
	for (int freeIndex : Lightmap.FreeTiles)
		if (freeIndex == index)
			I_FatalError("Duplicate LevelMesh lightmap tile free: %d", index);
	Lightmap.UsedTiles--;
	Lightmap.FreeTiles.Push(index);
	MarkMutation(LevelMeshMutationDomain::LightmapProbe);
}

stats.content:
LevelMeshTileStats LevelMesh::GatherTilePixelStats()
{
	LevelMeshTileStats stats;
	for (const LightmapTile& tile : Lightmap.Tiles)
	{
		auto area = tile.AtlasLocation.Area();

		stats.pixels.total += area;

		if (tile.NeedsInitialBake)
		{
			stats.tiles.dirty++;
			stats.pixels.dirty += area;
		}
	}
	stats.tiles.total += Lightmap.Tiles.Size();
	return stats;
}

release.content:
void DoomLevelMesh::ReleaseTiles(int surf)
{
	while (surf != -1)
	{
		int& tileIndex = Mesh.Surfaces[surf].LightmapTileIndex;
		if (tileIndex != -1)
		{
			LightmapTile& tile = Lightmap.Tiles[tileIndex];
			tile.UseCount--;
			if (tile.UseCount == 0) // Nothing is referencing this tile anymore. Release it back to the atlas packer.
			{
				if (tile.AtlasLocation.Item)
				{
					Lightmap.AtlasPacker->Free(tile.AtlasLocation.Item);
					tile.AtlasLocation.Item = nullptr;
				}
				FreeTile(tileIndex);
			}
			tileIndex = -1;
		}
		surf = DoomSurfaceInfos[surf].NextSurface;
	}
}

save.content:
void DoomLevelMesh::SaveLightmapLump(FLevelLocals& doomMap)
{
	/*
	// LIGHTMAP version 4 pseudo-C specification:

	(Please update LIGHTMAPVER in version.h when upgrading this)

	struct LightmapLump
	{
		int version;
		uint32_t tileCount;
		uint32_t pixelCount;
		TileEntry tiles[surfaceCount];
		uint16_t pixels[pixelCount * 3];
	};

	struct TileEntry
	{
		uint32_t type, typeIndex;
		uint32_t controlSector; // 0xFFFFFFFF is none
		uint16_t width, height; // in pixels
		uint32_t pixelsOffset; // offset in pixels array
		vec3f translateWorldToLocal;
		vec3f projLocalToU;
		vec3f projLocalToV;
	};
	*/

	Lightmap.TextureData.Resize(Lightmap.TextureSize * Lightmap.TextureSize * Lightmap.TextureCount * 4);
	for (int arrayIndex = 0; arrayIndex < Lightmap.TextureCount; arrayIndex++)
	{
		screen->DownloadLightmap(arrayIndex, Lightmap.TextureData.Data() + arrayIndex * Lightmap.TextureSize * Lightmap.TextureSize * 4);
	}

	// Calculate size of lump
	uint32_t tileCount = 0;
	uint32_t pixelCount = 0;

	for (unsigned int i = 0; i < Lightmap.Tiles.Size(); i++)
	{
		LightmapTile* tile = &Lightmap.Tiles[i];
		if (tile->AtlasLocation.ArrayIndex != -1 && tile->AtlasLocation.ArrayIndex < Lightmap.TextureCount)
		{
			tileCount++;
			pixelCount += tile->AtlasLocation.Area();
		}
	}

	const int version = LIGHTMAPVER;

	const uint32_t headerSize = sizeof(int) + 2 * sizeof(uint32_t);
	const uint32_t bytesPerTileEntry = sizeof(uint32_t) * 4 + sizeof(uint16_t) * 2 + sizeof(float) * 9;
	const uint32_t bytesPerPixel = sizeof(uint16_t) * 3; // F16 RGB

	uint32_t lumpSize = headerSize + tileCount * bytesPerTileEntry + pixelCount * bytesPerPixel;

	LumpWriter lumpFile(lumpSize);

	// Write header
	lumpFile.Write32(version);
	lumpFile.Write32(tileCount);
	lumpFile.Write32(pixelCount);

	// Write tiles
	uint32_t pixelsOffset = 0;

	for (unsigned int i = 0; i < Lightmap.Tiles.Size(); i++)
	{
		LightmapTile* tile = &Lightmap.Tiles[i];

		if (tile->AtlasLocation.ArrayIndex == -1 || tile->AtlasLocation.ArrayIndex >= Lightmap.TextureCount)
			continue;

		lumpFile.Write32(tile->Binding.Type);
		lumpFile.Write32(tile->Binding.TypeIndex);
		lumpFile.Write32(tile->Binding.ControlSector);

		lumpFile.Write16(uint16_t(tile->AtlasLocation.Width));
		lumpFile.Write16(uint16_t(tile->AtlasLocation.Height));

		lumpFile.Write32(pixelsOffset * 3);

		lumpFile.WriteFloat(tile->Transform.TranslateWorldToLocal.X);
		lumpFile.WriteFloat(tile->Transform.TranslateWorldToLocal.Y);
		lumpFile.WriteFloat(tile->Transform.TranslateWorldToLocal.Z);

		lumpFile.WriteFloat(tile->Transform.ProjLocalToU.X);
		lumpFile.WriteFloat(tile->Transform.ProjLocalToU.Y);
		lumpFile.WriteFloat(tile->Transform.ProjLocalToU.Z);

		lumpFile.WriteFloat(tile->Transform.ProjLocalToV.X);
		lumpFile.WriteFloat(tile->Transform.ProjLocalToV.Y);
		lumpFile.WriteFloat(tile->Transform.ProjLocalToV.Z);

		pixelsOffset += tile->AtlasLocation.Area();
	}

	// Write surface pixels
	for (unsigned int i = 0; i < Lightmap.Tiles.Size(); i++)
	{
		LightmapTile* tile = &Lightmap.Tiles[i];

		if (tile->AtlasLocation.ArrayIndex == -1 || tile->AtlasLocation.ArrayIndex >= Lightmap.TextureCount)
			continue;

		const uint16_t* pixels = Lightmap.TextureData.Data() + tile->AtlasLocation.ArrayIndex * Lightmap.TextureSize * Lightmap.TextureSize * 4;
		int width = tile->AtlasLocation.Width;
		int height = tile->AtlasLocation.Height;
		for (int y = 0; y < height; y++)
		{
			const uint16_t* srcline = pixels + (tile->AtlasLocation.X + (tile->AtlasLocation.Y + y) * Lightmap.TextureSize) * 4;
			for (int x = 0; x < width; x++)
			{
				lumpFile.Write16(*(srcline++));
				lumpFile.Write16(*(srcline++));
				lumpFile.Write16(*(srcline++));
				srcline++;
			}
		}
	}

	FString fullpath = GetMapFilename(doomMap);
	if (fullpath.Len() == 0)
		return;

	Printf("Saving LIGHTMAP lump into %s\n", fullpath.GetChars());

	FileReader reader;
	if (!reader.OpenFile(fullpath.GetChars()))
	{
		I_Error("Could not open map WAD file");
		return;
	}

	TArray<MapLump> lumps = LoadMapLumps(&reader, "PWAD");
	if (lumps.Size() == 0)
	{
		I_Error("Could not read map WAD file");
		return;
	}

	reader.Close();

	int lightmapIndex = -1;
	int endmapIndex = lumps.size();
	FString strLightmap = "LIGHTMAP";
	FString strEndmap = "ENDMAP";
	for (int i = 0, count = lumps.size(); i < count; i++)
	{
		if (lumps[i].Name == strLightmap)
			lightmapIndex = i;
		else if (lumps[i].Name == strEndmap)
			endmapIndex = i;
	}

	if (lightmapIndex != -1)
		lumps[lightmapIndex].Data = lumpFile.DeflateCompress();
	else
		lumps.Insert(endmapIndex, { "LIGHTMAP", lumpFile.DeflateCompress()});

	std::unique_ptr<FileWriter> writer(FileWriter::Open(fullpath.GetChars()));
	if (writer)
	{
		SaveMapLumps(writer.get(), lumps, "PWAD");
	}
	else
	{
		I_Error("Could not write map WAD file");
	}
}

invalidate.content:
static int InvalidateLightmap()
{
	int count = 0;

	for (auto& tile : level.levelMesh->Lightmap.Tiles)
	{
		if (!tile.NeedsInitialBake)
			++count;
		tile.NeedsInitialBake = true;
	}

	return count;
}

update.content:
void HWDrawInfo::UpdateLightmaps()
{
	if (outer)
		outer->UpdateLightmaps();

	VisibleTiles.Result.Clear();

	size_t max_updates = (size_t)lm_max_updates;

	// We always must bake tiles that received new geometry
	for (auto tile : VisibleTiles.Geometry)
		VisibleTiles.Result.Push(tile);

	if (VisibleTiles.Result.size() < max_updates)
	{
		// We got room for more. Include some visible tiles that are being background updated
		for (auto tile : VisibleTiles.Background)
			VisibleTiles.Result.Push(tile);

		if (VisibleTiles.Result.size() < max_updates)
		{
			// We still have room. Add tiles that received new light
			for (auto tile : VisibleTiles.ReceivedNewLight)
				VisibleTiles.Result.Push(tile);

			if (VisibleTiles.Result.size() < max_updates)
			{
				max_updates = VisibleTiles.Result.size() + (size_t)lm_background_updates;

				// Look for more background updates
				for (auto& e : level.levelMesh->Lightmap.Tiles)
				{
					if (e.NeedsInitialBake && e.LastSeen != TileSeenCounter)
					{
						VisibleTiles.Result.Push(&e);
						if (VisibleTiles.Result.size() >= max_updates)
							break;
					}
				}
			}
			else
			{
				VisibleTiles.Result.resize(max_updates);
			}
		}
		else
		{
			VisibleTiles.Result.resize(max_updates);
		}
	}

	screen->UpdateLightmaps(VisibleTiles.Result);

	VisibleTiles.Geometry.Clear();
	VisibleTiles.Background.Clear();
	VisibleTiles.ReceivedNewLight.Clear();
	VisibleTiles.Result.Clear();
}

frame.content:
void VulkanRenderDevice::BeginFrame()
{
	CfxTrace::NextFrame();
	CfxTrace::Stage cfxStage("resource-mesh-upload");
	vmaSetCurrentFrameIndex(mDevice->allocator, 0);
	membudgets.Resize(mDevice->PhysicalDevice.Properties.Memory.memoryHeapCount);
	vmaGetHeapBudgets(mDevice->allocator, membudgets.data());
	if (memheapnames.size() == 0)
	{
		memheapnames.Resize(mDevice->PhysicalDevice.Properties.Memory.memoryHeapCount);
		for (unsigned int i = 0; i < memheapnames.Size(); i++)
		{
			bool deviceLocal = !!(mDevice->PhysicalDevice.Properties.Memory.memoryHeaps[i].flags & VK_MEMORY_HEAP_DEVICE_LOCAL_BIT);
			memheapnames[i] = deviceLocal ? " (device local)" : "";
		}
	}
	hwtexturecount = mTextureManager->GetHWTextureCount();

	FrameTileUpdates = 0;

	GetRenderPassManager()->ProcessMainThreadTasks();
	GetTextureManager()->ProcessMainThreadTasks();

	if (levelMeshChanged)
	{
		levelMeshChanged = false;
		mLevelMesh->SetLevelMesh(levelMesh);
		GetTextureManager()->CreateLightmap(levelMesh->Lightmap.TextureSize, levelMesh->Lightmap.TextureCount, std::move(levelMesh->Lightmap.TextureData));
		GetLightmapper()->SetLevelMesh(levelMesh);
	}

	SetViewportRects(nullptr);
	mCommands->BeginFrame();
	mLevelMesh->BeginFrame();
	mTextureManager->BeginFrame(levelMesh->Lightmap.TextureSize, levelMesh->Lightmap.TextureCount);
	mScreenBuffers->BeginFrame(screen->mScreenViewport.width, screen->mScreenViewport.height, screen->mSceneViewport.width, screen->mSceneViewport.height);
	mSaveBuffers->BeginFrame(SAVEPICWIDTH, SAVEPICHEIGHT, SAVEPICWIDTH, SAVEPICHEIGHT);
	mRenderState->BeginFrame();
	mDescriptorSetManager->BeginFrame();
	mLightmapper->BeginFrame();
}

probe_step.content:
void LightProbeIncrementalBuilder::Step(const TArray<LightProbe>& probes, std::function<void(int probeIndex, const LightProbe& probe)> renderScene)
{
	if (probes.size() == 0)
	{
		if (cubemapsAllocated != 0)
			screen->ResetLightProbes();
		lastIndex = 0;
		collected = 0;
		cubemapsAllocated = 0;
		iterations = 0;
		return;
	}

	if (cubemapsAllocated != probes.size())
	{
		cubemapsAllocated = probes.size();
		lastIndex = 0;
		collected = 0;
		iterations = 0;
		screen->ResetLightProbes();
		return;
	}

	if (iterations >= 5)
		return; // We are done baking

	if (lastIndex >= probes.size())
		lastIndex = 0;

	renderScene(lastIndex, probes[lastIndex]);
	lastIndex++;
	collected++;

	if (lastIndex >= probes.size())
	{
		if (collected == probes.size())
			screen->EndLightProbePass();
		collected = 0;
		iterations++;
	}
}

probe_full.content:
void LightProbeIncrementalBuilder::Full(const TArray<LightProbe>& probes, std::function<void(int probeIndex, const LightProbe& probe)> renderScene)
{
	if (probes.size() == 0)
	{
		Step(probes, renderScene);
		return;
	}

	if (cubemapsAllocated == probes.size() && iterations >= 5)
		return;

	if (lastIndex >= probes.size())
		lastIndex = 0;

	while (lastIndex < probes.size())
	{
		const int previousIndex = lastIndex;
		const int previousAllocated = cubemapsAllocated;
		const int previousIterations = iterations;
		Step(probes, renderScene);

		// Step must either advance the pass or change builder state. This guard
		// makes Full fail closed instead of spinning if a future terminal state
		// is added to Step without a corresponding Full update.
		if (lastIndex == previousIndex && cubemapsAllocated == previousAllocated && iterations == previousIterations)
			return;

		if (iterations >= 5 || lastIndex >= probes.size())
			return;
	}
}
